// What a file shows is what every check reaching it reports. The program
// takes `util` after a file of `sub`, which nothing imports, already did, and
// `sub` dropping it leaves the program's report of `util.lin` standing.
fn main() -> UInt8 {
    0
}

import util

pub fn twice() -> UInt8 {
    util.value() + util.value()
}

